"use client"
import { useState } from "react";

export default function AdminLogin() {
  const [showPassword, setShowPassword] = useState(false);

  return (

    <div className=" w-full h-screen">
    <div className="text-center py-25 text-2xl md:text-3xl font-semibold">Welcome Admin</div>
    <div className="flex flex-col max-w-xs md:max-w-lg mx-auto justify-center gap-4 ">
      <input
        type="text"
        placeholder="Name"
        className="border w-full p-2 rounded"
      />

      <div className="relative w-full max-w-xs md:max-w-lg ">
        <input
          type={showPassword ? "text" : "password"}
          placeholder="Password"
          className="border p-2 rounded w-full pr-10"
        />
        <button
          type="button"
          onClick={() => setShowPassword(!showPassword)}
          className="absolute right-2 top-1/2 transform -translate-y-1/2 text-gray-500"
        >
          {showPassword ? "Hide" : "Show"}
        </button>
      </div>

      <button type="submit" className="bg-gray-500 text-white px-4 py-2 rounded mt-2 hover:cursor-pointer">
        Login
      </button>
    </div>
    </div>
  );
}
